public void processData() {
    try {
        // Catching Exception is correct for business recovery
        performIoOperation();
    } catch (IOException e) {
        logger.error("Recoverable failure", e);
    } catch (Throwable t) {
        // Anti-pattern: Catching Error prevents the JVM from shutting down gracefully
        // during critical failures like OutOfMemoryError.
        throw t;
    }
}
